p='src/dates.js'
s=open(p).read()
s=s.replace('''  const next = new Date(date.getTime());
  next.setUTCMonth(next.getUTCMonth() + months);
  return next;''','''  const target = date.getUTCMonth() + months;
  const year = date.getUTCFullYear() + Math.floor(target / 12);
  const month = ((target % 12) + 12) % 12;
  // Day 0 of the following month is the last day of the target month.
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
  return new Date(Date.UTC(year, month, Math.min(date.getUTCDate(), lastDay)));''')
open(p,'w').write(s)
p='src/schedule.js'
s=open(p).read()
s=s.replace('''  let current = start;
  for (let i = 0; i < count; i++) {
    current = addMonths(current, step);
    dates.push(current);
  }''','''  // Always offset from the start date so a clamped day (31 Jan -> 29 Feb)
  // doesn't stick for later renewals (29 Feb -> 31 Mar).
  for (let i = 1; i <= count; i++) {
    dates.push(addMonths(start, step * i));
  }''')
open(p,'w').write(s)
E
